1	// Validates every article in content/seo/ against the contract that
2	// app/blog/[slug]/page.tsx and app/blog/page.tsx actually impose.
3	//
4	// The render contract, read off the code rather than assumed:
5	//   - app/blog/[slug]/page.tsx injects `post.bodyHtml` with
6	//     dangerouslySetInnerHTML into a plain <div className="article-body">.
7	//     Nothing sanitises it and nothing wraps it, so the stored string has to be
8	//     a complete, well-formed run of block-level elements on its own.
9	//   - The page already renders `post.title` as the one <h1>, so an article that
10	//     ships its own <h1> produces a second one.
11	//   - app/globals.css styles ONLY these inside .article-body: h2, h3, p, ul, ol,
12	//     li, a, strong, code, table, th, td, blockquote. Anything else renders
13	//     unstyled — a <pre> block, for instance, would run off the page.
14	//   - readingTime() strips tags with /<[^>]+>/g, so a literal ">" inside an
15	//     attribute value would corrupt the word count.
16	//
17	// Plus the product constraint: a Kodely article must not reference a remote
18	// host. The marketing site is not under the generated-site CSP, but shipping
19	// third-party requests from a page whose whole argument is "no external
20	// requests" is a bad look, and an <img> would be an unstyled full-bleed image.
21	//
22	// Usage:  node scripts/seo/validate.mjs [--quiet]
23	
24	import { pathToFileURL } from "node:url";
25	import { loadArticles } from "./lib.mjs";
26	
27	const QUIET = process.argv.includes("--quiet");
28	
29	// Styled by .article-body in app/globals.css, plus the structural table
30	// elements those styles imply and <em> (browser default italic is fine).
31	const ALLOWED_TAGS = new Set([
32	  "p",
33	  "h2",
34	  "h3",
35	  "ul",
36	  "ol",
37	  "li",
38	  "a",
39	  "strong",
40	  "em",
41	  "code",
42	  "blockquote",
43	  "table",
44	  "thead",
45	  "tbody",
46	  "tr",
47	  "th",
48	  "td",
49	]);
50	
51	// A body block must START with one of these — the article is a sequence of
52	// block-level elements, never a bare run of text.
53	const BLOCK_TAGS = new Set(["p", "h2", "h3", "ul", "ol", "blockquote", "table"]);
54	
55	// Matches the board columns the blog index groups on.
56	const ALLOWED_CATEGORIES = new Set(["Guides", "Explainers", "Comparisons"]);
57	
58	const TITLE_MAX = 60;
59	const META_MIN = 50;
60	const META_MAX = 160;
61	
62	const TAG_RE = /<\/?([a-zA-Z][a-zA-Z0-9]*)((?:[^>"']|"[^"]*"|'[^']*')*?)\s*\/?>/g;
63	const ENTITY_RE = /&(?:[a-zA-Z][a-zA-Z0-9]{1,9}|#\d{1,6}|#x[0-9a-fA-F]{1,6});/g;
64	
65	// Anything that would make the page fetch from, or point at, another origin.
66	const EXTERNAL_PATTERNS = [
67	  [/\bsrc\s*=/i, "src= attribute (no external or inline assets in article bodies)"],
68	  [/\bsrcset\s*=/i, "srcset attribute"],
69	  [/https?:\/\//i, "absolute http(s) URL"],
70	  [/(^|[^:])\/\/[a-z0-9-]+\.[a-z]{2,}/i, "protocol-relative URL"],
71	  [/url\s*\(/i, "CSS url()"],
72	  [/@import/i, "@import"],
73	  [/\bstyle\s*=/i, "inline style attribute"],
74	  [/\bon[a-z]+\s*=\s*["']/i, "inline event handler"],
75	];
76	
77	/**
78	 * Walks the tag stream keeping a stack. Returns the list of structural
79	 * problems: unknown tags, mismatched closes, anything left open at the end.
80	 */
81	function checkStructure(html) {
82	  const problems = [];
83	  const stack = [];
84	  let match;
85	  TAG_RE.lastIndex = 0;
86	
87	  while ((match = TAG_RE.exec(html)) !== null) {
88	    const [full, rawName] = match;
89	    const name = rawName.toLowerCase();
90	    const isClose = full.startsWith("</");
91	    const isSelfClosing = /\/>$/.test(full);
92	
93	    if (name === "h1") {
94	      problems.push("<h1> is reserved for post.title, which the page renders itself");
95	      continue;
96	    }
97	    if (!ALLOWED_TAGS.has(name)) {
98	      problems.push(`<${name}> is not styled by .article-body in app/globals.css`);
99	      continue;
100	    }
101	    if (isSelfClosing) {
102	      problems.push(`<${name} /> — self-closing tags are not used in article bodies`);
103	      continue;
104	    }
105	
106	    if (isClose) {
107	      const open = stack.pop();
108	      if (open === undefined) {
109	        problems.push(`</${name}> closes a tag that was never opened`);
110	      } else if (open !== name) {
111	        problems.push(`</${name}> closes while <${open}> is still open`);
112	      }
113	    } else {
114	      stack.push(name);
115	    }
116	  }
117	
118	  for (const open of stack.reverse()) {
119	    problems.push(`<${open}> is never closed`);
120	  }
121	
122	  // Anything with a "<" that the tag regex could not consume is malformed
123	  // markup — a stray bracket, an unquoted attribute, a broken close.
124	  const stripped = html.replace(TAG_RE, "");
125	  if (stripped.includes("<")) {
126	    problems.push("a '<' remains after tag parsing — malformed markup");
127	  }
128	  if (stripped.includes(">")) {
129	    problems.push("a bare '>' in text — escape it as &gt; (readingTime strips on '>')");
130	  }
131	
132	  // A bare "&" breaks in some feed/consumer contexts and is trivially avoided.
133	  const ampersands = stripped.replace(ENTITY_RE, "");
134	  if (ampersands.includes("&")) {
135	    problems.push("an unescaped '&' in text — write it as &amp;");
136	  }
137	
138	  return problems;
139	}
140	
141	function checkLinks(html, knownSlugs) {
142	  const problems = [];
143	  for (const match of html.matchAll(/<a\s+href="([^"]*)"/g)) {
144	    const href = match[1];
145	    if (!href.startsWith("/") && !href.startsWith("#")) {
146	      problems.push(`link "${href}" is not a root-relative or in-page link`);
147	      continue;
148	    }
149	    const blog = href.match(/^\/blog\/([a-z0-9-]+)$/);
150	    if (blog && !knownSlugs.has(blog[1])) {
151	      problems.push(`link "${href}" points at an article that is not in content/seo/`);
152	    }
153	  }
154	  for (const match of html.matchAll(/<a\b((?:[^>"]|"[^"]*")*)>/g)) {
155	    if (!/\shref="/.test(match[1])) {
156	      problems.push("an <a> without a quoted href");
157	    }
158	  }
159	  return problems;
160	}
161	
162	function validate(article, seen, knownSlugs) {
163	  const problems = [];
164	  const warnings = [];
165	  const { slug, title, metaDescription, category, targetKeyword, bodyHtml, body } = article;
166	
167	  // ── Identity ──────────────────────────────────────────────────────────
168	  if (typeof slug !== "string" || !slug) {
169	    problems.push("slug is missing");
170	  } else {
171	    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
172	      problems.push(`slug "${slug}" must be lowercase words joined by single hyphens`);
173	    }
174	    if (slug !== article.expectedSlug) {
175	      problems.push(`slug "${slug}" does not match its filename (${article.file})`);
176	    }
177	    if (seen.slugs.has(slug)) problems.push(`slug "${slug}" is used by another article`);
178	    seen.slugs.add(slug);
179	  }
180	
181	  // ── Title ─────────────────────────────────────────────────────────────
182	  if (typeof title !== "string" || !title.trim()) {
183	    problems.push("title is missing");
184	  } else {
185	    if (title.length > TITLE_MAX) {
186	      problems.push(`title is ${title.length} chars (max ${TITLE_MAX}) — Google truncates past this`);
187	    }
188	    if (seen.titles.has(title)) problems.push(`title "${title}" is used by another article`);
189	    seen.titles.add(title);
190	  }
191	
192	  // ── Meta description ──────────────────────────────────────────────────
193	  if (typeof metaDescription !== "string" || !metaDescription.trim()) {
194	    problems.push("metaDescription is missing");
195	  } else {
196	    const n = metaDescription.length;
197	    if (n < META_MIN || n > META_MAX) {
198	      problems.push(`metaDescription is ${n} chars (want ${META_MIN}-${META_MAX})`);
199	    }
200	    if (/<[a-z]/i.test(metaDescription)) {
201	      problems.push("metaDescription contains markup — it is rendered as plain text");
202	    }
203	    if (seen.metas.has(metaDescription)) {
204	      problems.push("metaDescription duplicates another article's");
205	    }
206	    seen.metas.add(metaDescription);
207	  }
208	
209	  // ── Taxonomy ──────────────────────────────────────────────────────────
210	  if (!ALLOWED_CATEGORIES.has(category)) {
211	    problems.push(`category "${category}" is not one of: ${[...ALLOWED_CATEGORIES].join(", ")}`);
212	  }
213	  if (typeof targetKeyword !== "string" || !targetKeyword.trim()) {
214	    problems.push("targetKeyword is missing");
215	  } else if (targetKeyword !== targetKeyword.toLowerCase()) {
216	    problems.push("targetKeyword should be lowercase");
217	  }
218	
219	  // ── Body ──────────────────────────────────────────────────────────────
220	  if (!Array.isArray(body) || body.length === 0) {
221	    problems.push("body must be a non-empty array of block-level HTML strings");
222	  } else {
223	    body.forEach((block, i) => {
224	      if (typeof block !== "string" || !block.trim()) {
225	        problems.push(`body[${i}] is empty`);
226	        return;
227	      }
228	      const opener = block.match(/^<([a-zA-Z][a-zA-Z0-9]*)[\s>]/);
229	      if (!opener || !BLOCK_TAGS.has(opener[1].toLowerCase())) {
230	        problems.push(`body[${i}] does not start with a block element (${block.slice(0, 40)}…)`);
231	      }
232	    });
233	
234	    for (const [pattern, label] of EXTERNAL_PATTERNS) {
235	      if (pattern.test(bodyHtml)) problems.push(`body references ${label}`);
236	    }
237	
238	    problems.push(...checkStructure(bodyHtml));
239	    problems.push(...checkLinks(bodyHtml, knownSlugs));
240	
241	    const words = bodyHtml.replace(/<[^>]+>/g, " ").trim().split(/\s+/).filter(Boolean).length;
242	    if (words < 400) warnings.push(`only ${words} words — thin for a page meant to rank`);
243	    if (!/<h2[\s>]/.test(bodyHtml)) warnings.push("no <h2> — long pages need scannable headings");
244	    if (!/<a\s+href="\/signup"/.test(bodyHtml) && !/<a\s+href="\/pricing"/.test(bodyHtml)) {
245	      warnings.push("no link to /signup or /pricing");
246	    }
247	  }
248	
249	  // An unknown or forbidden tag reports once per occurrence, which for a tag
250	  // used ten times is ten identical lines. De-duplicate — the fix is the same.
251	  return { problems: [...new Set(problems)], warnings: [...new Set(warnings)] };
252	}
253	
254	/**
255	 * Runs every check over every article on disk. Exported so the seeder can
256	 * refuse to write invalid content without shelling out to this file — one
257	 * implementation of the contract, two callers.
258	 */
259	export function validateAll(articles = loadArticles()) {
260	  const knownSlugs = new Set(articles.map((a) => a.slug));
261	  const seen = { slugs: new Set(), titles: new Set(), metas: new Set() };
262	  return articles.map((article) => ({
263	    article,
264	    ...validate(article, seen, knownSlugs),
265	  }));
266	}
267	
268	function main() {
269	  const articles = loadArticles();
270	  if (articles.length === 0) {
271	    console.error("No articles found in content/seo/.");
272	    process.exit(1);
273	  }
274	
275	  let failed = 0;
276	  let warned = 0;
277	
278	  for (const { article, problems, warnings } of validateAll(articles)) {
279	    if (problems.length > 0) {
280	      failed++;
281	      console.error(`\nFAIL  ${article.file}`);
282	      for (const p of problems) console.error(`  - ${p}`);
283	      for (const w of warnings) console.error(`  ~ ${w}`);
284	    } else if (warnings.length > 0) {
285	      warned++;
286	      if (!QUIET) {
287	        console.log(`WARN  ${article.file}`);
288	        for (const w of warnings) console.log(`  ~ ${w}`);
289	      }
290	    } else if (!QUIET) {
291	      const words = article.bodyHtml.replace(/<[^>]+>/g, " ").trim().split(/\s+/).length;
292	      console.log(`ok    ${article.slug}  (${article.title.length} char title, ${words} words)`);
293	    }
294	  }
295	
296	  console.log(
297	    `\n${articles.length} articles — ${articles.length - failed} valid, ${failed} failing, ${warned} with warnings.`,
298	  );
299	  process.exit(failed > 0 ? 1 : 0);
300	}
301	
302	// Only when run directly — importing this from seed.mjs must not exit.
303	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
304	  main();
305	}
