1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { notFound } from "next/navigation";
4	import { ArrowLeft, ArrowRight, Clock } from "lucide-react";
5	import { db } from "@/lib/db";
6	import { MarketingNav } from "@/components/marketing/MarketingNav";
7	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
8	import { Aura } from "@/components/marketing/Aura";
9	import { ArticleProgress } from "@/components/marketing/ArticleProgress";
10	import { Reveal } from "@/components/marketing/Reveal";
11	import { MotionLift } from "@/components/marketing/FloatCard";
12	import { ShineButton } from "@/components/marketing/ShineButton";
13	import { SkipLink } from "@/components/marketing/SkipLink";
14	
15	export const dynamic = "force-static";
16	export const revalidate = 3600;
17	
18	async function getPost(slug: string) {
19	  return db.blogPost.findUnique({ where: { slug } });
20	}
21	
22	function readingTime(html: string) {
23	  const words = html.replace(/<[^>]+>/g, " ").trim().split(/\s+/).filter(Boolean).length;
24	  return Math.max(1, Math.round(words / 200));
25	}
26	
27	export async function generateMetadata({
28	  params,
29	}: {
30	  params: Promise<{ slug: string }>;
31	}): Promise<Metadata> {
32	  const { slug } = await params;
33	  const post = await getPost(slug);
34	  if (!post) return {};
35	  return {
36	    title: post.title,
37	    description: post.metaDescription,
38	  };
39	}
40	
41	export default async function BlogPostPage({ params }: { params: Promise<{ slug: string }> }) {
42	  const { slug } = await params;
43	  const post = await getPost(slug);
44	  if (!post) notFound();
45	
46	  const related = await db.blogPost.findMany({
47	    where: { category: post.category, slug: { not: post.slug } },
48	    orderBy: { publishedAt: "desc" },
49	    select: { slug: true, title: true },
50	    take: 2,
51	  });
52	
53	  const minutes = readingTime(post.bodyHtml);
54	  const published = post.publishedAt.toLocaleDateString("en-US", {
55	    month: "long",
56	    day: "numeric",
57	    year: "numeric",
58	  });
59	
60	  return (
61	    <div className="relative min-h-screen bg-white text-neutral-900 dark:bg-neutral-950 dark:text-neutral-50">
62	      <SkipLink />
63	      <Aura />
64	      <ArticleProgress />
65	      <MarketingNav />
66	
67	      {/* <article> is semantic but is not a landmark, so on its own it gave the
68	          skip link nowhere to land. Wrapping rather than replacing keeps the
69	          article semantics intact. */}
70	      <main id="main-content" tabIndex={-1}>
71	      <article className="relative mx-auto max-w-3xl px-6 pb-24 pt-36 sm:pt-44">
72	        <Reveal>
73	          <Link
74	            href="/blog"
75	            className="inline-flex items-center gap-1.5 text-sm text-neutral-500 hover:text-neutral-900 dark:text-neutral-500 dark:hover:text-white"
76	          >
77	            <ArrowLeft size={14} /> All articles
78	          </Link>
79	        </Reveal>
80	
81	        {/* Liquid-glass article panel — frosted card floating over the page's
82	            ambient Aura blobs (which bleed through the translucent fill),
83	            with a soft specular highlight in the top-left corner, the same
84	            "iOS 26 liquid glass" language used on the homepage's PromptHero. */}
85	        <Reveal delay={0.06}>
86	          <div
87	            className="relative mt-6 overflow-hidden rounded-[2rem] border border-white/60 bg-white/55 p-8 shadow-[var(--sh-s)] backdrop-blur-2xl backdrop-saturate-150 sm:p-12 dark:border-white/10 dark:bg-white/[0.05]"
88	          >
89	            <div
90	              aria-hidden
91	              className="pointer-events-none absolute -left-24 -top-24 h-64 w-64 rounded-full opacity-60"
92	              style={{ background: "radial-gradient(closest-side, var(--glow), transparent)" }}
93	            />
94	            <div
95	              aria-hidden
96	              className="pointer-events-none absolute -bottom-32 -right-16 h-72 w-72 rounded-full opacity-50"
97	              style={{ background: "radial-gradient(closest-side, var(--glow-2), transparent)" }}
98	            />
99	
100	            <div className="relative">
101	              <div className="flex flex-wrap items-center gap-3 text-xs font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400">
102	                <span className="inline-flex items-center gap-1.5 rounded-full border border-neutral-200/70 bg-white/60 px-3 py-1 backdrop-blur-md dark:border-white/10 dark:bg-white/[0.06]">
103	                  <span
104	                    className="h-1.5 w-1.5 rounded-full"
105	                    style={{ background: "var(--brand-gradient)" }}
106	                    aria-hidden
107	                  />
108	                  {post.category}
109	                </span>
110	                <span className="inline-flex items-center gap-1.5 normal-case tracking-normal text-neutral-500 dark:text-neutral-500">
111	                  <Clock size={13} /> {minutes} min read
112	                </span>
113	                <span className="normal-case tracking-normal text-neutral-400 dark:text-neutral-600">{published}</span>
114	              </div>
115	
116	              <h1 className="mt-5 text-3xl font-semibold leading-tight tracking-tight sm:text-4xl">{post.title}</h1>
117	
118	              <div className="article-body mt-10" dangerouslySetInnerHTML={{ __html: post.bodyHtml }} />
119	            </div>
120	          </div>
121	        </Reveal>
122	
123	        <Reveal delay={0.1}>
124	          <div className="relative mt-10 overflow-hidden rounded-[1.75rem] border border-white/60 bg-white/55 p-8 text-center shadow-[var(--sh-s)] backdrop-blur-2xl backdrop-saturate-150 dark:border-white/10 dark:bg-white/[0.05]">
125	            <div
126	              aria-hidden
127	              className="pointer-events-none absolute left-1/2 top-1/2 -z-0 -translate-x-1/2 -translate-y-1/2 rounded-full opacity-70 blur-[70px]"
128	              style={{ width: "70%", height: "160%", background: "radial-gradient(closest-side, var(--glow), transparent)" }}
129	            />
130	            <div className="relative">
131	              <h2 className="text-xl font-semibold tracking-tight">Ready to build your own site?</h2>
132	              <p className="mx-auto mt-2 max-w-md text-sm text-neutral-600 dark:text-neutral-400">
133	                750 free credits, no card required — describe it and watch a real
134	                React app come together.
135	              </p>
136	              <ShineButton className="mt-5">
137	                <Link
138	                  href="/signup"
139	                  className="btn-cta-gradient inline-block rounded-lg px-6 py-2.5 text-sm font-medium text-white"
140	                >
141	                  Start building — free
142	                </Link>
143	              </ShineButton>
144	            </div>
145	          </div>
146	        </Reveal>
147	
148	        {related.length > 0 && (
149	          <Reveal delay={0.12}>
150	            <div className="mt-14">
151	              <h3 className="text-sm font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400">
152	                Related reading
153	              </h3>
154	              <div className="mt-4 space-y-3">
155	                {related.map((r) => (
156	                  <MotionLift key={r.slug} lift={3}>
157	                    <Link
158	                      href={`/blog/${r.slug}`}
159	                      className="group flex items-center justify-between gap-3 rounded-2xl border border-white/60 bg-white/50 px-5 py-3.5 text-sm font-medium backdrop-blur-xl transition-colors hover:border-neutral-300 dark:border-white/10 dark:bg-white/[0.04] dark:hover:border-neutral-700"
160	                    >
161	                      {r.title}
162	                      <ArrowRight size={14} className="shrink-0 text-neutral-400 transition-transform group-hover:translate-x-1" />
163	                    </Link>
164	                  </MotionLift>
165	                ))}
166	              </div>
167	            </div>
168	          </Reveal>
169	        )}
170	      </article>
171	      </main>
172	
173	      <MarketingFooter />
174	    </div>
175	  );
176	}
