1	// Shared plumbing for the SEO content pipeline.
2	//
3	// Articles live as one JSON file per post under content/seo/. Body copy is an
4	// ARRAY of block-level HTML strings rather than one giant escaped string: it
5	// keeps diffs readable, keeps line length sane, and makes it obvious when a
6	// block was added or removed. `bodyHtml` — the column the DB actually stores —
7	// is derived here by joining those blocks, so there is exactly one definition
8	// of the transform and the validator and the seeder can never disagree.
9	
10	import { readFileSync, readdirSync, existsSync } from "node:fs";
11	import { dirname, join, resolve, basename } from "node:path";
12	import { fileURLToPath } from "node:url";
13	
14	export const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
15	export const CONTENT_DIR = join(REPO_ROOT, "content", "seo");
16	
17	/**
18	 * Minimal .env reader. Deliberately not a dependency: this pipeline must run
19	 * with nothing installed beyond what the app already has, and the only thing
20	 * it needs out of .env is DATABASE_URL.
21	 *
22	 * Never overwrites a variable that is already set, so `DATABASE_URL=... node
23	 * scripts/seo/seed.mjs` still points where the operator aimed it.
24	 */
25	export function loadEnv(file = join(REPO_ROOT, ".env")) {
26	  if (!existsSync(file)) return;
27	  for (const rawLine of readFileSync(file, "utf8").split(/\r?\n/)) {
28	    const line = rawLine.trim();
29	    if (!line || line.startsWith("#")) continue;
30	    const match = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
31	    if (!match) continue;
32	    const [, key, rawValue] = match;
33	    if (process.env[key] !== undefined) continue;
34	    let value = rawValue.trim();
35	    if (
36	      (value.startsWith('"') && value.endsWith('"') && value.length > 1) ||
37	      (value.startsWith("'") && value.endsWith("'") && value.length > 1)
38	    ) {
39	      value = value.slice(1, -1);
40	    }
41	    process.env[key] = value;
42	  }
43	}
44	
