35	/**
36	 * CreditLedger.reason is free text and carries three different encodings —
37	 * plain words ("build", "signup_grant"), a Stripe session id, and the social
38	 * reward state machine (app/api/rewards/_lib.ts) whose reason string embeds an
39	 * identity HASH. Rendering those raw would put a 64-char hex blob in the
40	 * middle of a billing statement, so decode them into something a human can
41	 * scan. The raw string is still shown on hover via `title`.
42	 */
43	export function reasonLabel(reason: string): string {
44	  if (reason === "build") return "Build";
45	  if (reason === "signup_grant") return "Signup grant";
46	  if (reason.startsWith("stripe:")) return "Credit purchase";
47	  if (reason.startsWith("reward:")) {
48	    const parts = reason.split(":");
49	    const platform = parts[1] ?? "";
50	    const name = platform ? platform[0].toUpperCase() + platform.slice(1) : "Social";
51	    return parts[2] === "pending" ? `${name} reward (pending)` : `${name} reward`;
52	  }
53	  return reason.replace(/_/g, " ");
54	}
