1	"use server";
2	
3	import { refresh } from "next/cache";
4	import { getAdminUser } from "@/lib/auth";
5	import { clampRolloutPct, deleteOrphanFlag, seedFlags, setFlag } from "@/lib/flags";
6	
7	// Server Actions for /admin/flags.
8	//
9	// A Server Action is a POST endpoint against the page, reachable by anyone who
10	// can send the request — rendering the form only on an admin page is not an
11	// authorization boundary (see the Next.js Server Actions guide, and the same
12	// argument in getAdminUser's doc comment). So every action re-checks admin
13	// itself and fails loudly. These writes turn generation and credit grants on
14	// and off; a silent no-op on a missed check would be far worse than a 500.
15	
16	async function requireAdminEmail(): Promise<string> {
17	  const admin = await getAdminUser();
18	  if (!admin) throw new Error("FORBIDDEN");
19	  // `updatedBy` is free text on the row; the email is what an incident review
20	  // actually wants to read. It is already visible throughout /admin/users.
21	  return admin.email;
22	}
23	
24	function flagKeyFrom(formData: FormData): string {
25	  const key = formData.get("key");
26	  if (typeof key !== "string" || !key) throw new Error("Missing flag key");
27	  // Not validated against FLAGS here — setFlag and deleteOrphanFlag each
28	  // enforce their own, opposite, membership rule.
29	  return key;
30	}
31	
32	/**
33	 * One action for all three row buttons, distinguished by `intent`, so the row
34	 * stays a single plain <form> that works without JavaScript.
35	 *
36	 * `on` and `off` deliberately send NO percentage: the kill button does exactly
37	 * one thing, and never commits a number the operator was still editing.
38	 */
39	export async function saveFlagAction(formData: FormData): Promise<void> {
40	  const updatedBy = await requireAdminEmail();
41	  const key = flagKeyFrom(formData);
42	  const intent = formData.get("intent");
43	
44	  if (intent === "on" || intent === "off") {
45	    await setFlag(key, { enabled: intent === "on" }, updatedBy);
46	  } else if (intent === "rollout") {
47	    const raw = Number.parseInt(String(formData.get("rolloutPct") ?? ""), 10);
48	    if (!Number.isFinite(raw)) throw new Error("Rollout percentage must be a number");
49	    await setFlag(key, { rolloutPct: clampRolloutPct(raw) }, updatedBy);
50	  } else {
51	    throw new Error(`Unknown intent: ${String(intent)}`);
52	  }
53	
54	  // The page is force-dynamic, so there is no cached data to invalidate — the
55	  // stored value just needs to be re-read and re-rendered. `refresh()` does
56	  // exactly that and ships the new RSC payload in this same response, so the
57	  // operator sees the flag's real state without a second round trip.
58	  refresh();
59	}
60	
61	export async function seedFlagsAction(): Promise<void> {
62	  const updatedBy = await requireAdminEmail();
63	  await seedFlags(updatedBy);
64	  refresh();
65	}
66	
67	export async function deleteOrphanFlagAction(formData: FormData): Promise<void> {
68	  await requireAdminEmail();
69	  await deleteOrphanFlag(flagKeyFrom(formData));
70	  refresh();
71	}
