1	// Applies targeted, reviewable corrections to ALREADY-PUBLISHED BlogPost rows.
2	//
3	//   node scripts/seo/correct-live.mjs                      dry run, every ungated group
4	//   node scripts/seo/correct-live.mjs --apply              write them
5	//   node scripts/seo/correct-live.mjs --group credit-figure
6	//   node scripts/seo/correct-live.mjs --gate export-shipped --apply
7	//   node scripts/seo/correct-live.mjs --emit-stubs         write the residue as a fill-in file
8	//
9	// WHY THIS IS NOT seed.mjs
10	// seed.mjs owns content/seo/*.json — articles whose full text lives in this
11	// repo. The 56 posts already live on kodely.me do not: their only source of
12	// truth is the BlogPost table on the production box. There is nothing here to
13	// diff a whole body against, so a correction has to be a surgical
14	// find-and-replace on the row's existing bodyHtml.
15	//
16	// THE FOUR PROPERTIES THIS IS BUILT AROUND
17	//
18	// 1. LITERAL MATCHES ONLY. Every edit is an exact string, never a regex.
19	//    Regex-rewriting live prose is how you turn one wrong sentence into
20	//    fifty mangled ones. A literal that no longer matches changes nothing
21	//    and is reported loudly instead — the failure mode is "did nothing",
22	//    never "did something surprising".
23	//
24	// 2. IDEMPOTENT. An edit whose `find` is gone and whose `replace` is already
25	//    present is reported as `done` and skipped. Re-running is a no-op, and
26	//    only bodyHtml is ever written, so @updatedAt does not churn.
27	//
28	// 3. NON-DESTRUCTIVE. Updates rows by slug. No create path, no delete path.
29	//    A slug in the corrections file with no row in the database is reported,
30	//    not inserted.
31	//
32	// 4. IT CHECKS ITS OWN WORK. Each group carries `detect` patterns describing
33	//    the claim being corrected. After planning, every row in the database is
34	//    swept for them — including the 42 live posts this repo has no copy of.
35	//    Residue is printed with context and makes the run exit non-zero, so
36	//    "the script said OK" cannot mean "some post you forgot still says it".
37	//
38	// GATES
39	// A group with `"gate": "export-shipped"` does not run unless
40	// `--gate export-shipped` is passed. That is deliberate: those corrections
41	// are only TRUE once the export route is deployed, so the flag is the
42	// operator asserting that it is. See content/seo/corrections/README.
43	
44	import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
45	import { join } from "node:path";
46	import { PrismaClient } from "@prisma/client";
47	import { loadEnv, CONTENT_DIR } from "./lib.mjs";
48	
49	const ARGV = process.argv.slice(2);
50	const APPLY = ARGV.includes("--apply");
51	const EMIT_STUBS = ARGV.includes("--emit-stubs");
52	const CORRECTIONS_DIR = join(CONTENT_DIR, "corrections");
53	
54	function argValues(flag) {
55	  const out = [];
56	  for (let i = 0; i < ARGV.length - 1; i++) if (ARGV[i] === flag) out.push(ARGV[i + 1]);
57	  return out;
58	}
59	const ONLY_GROUPS = argValues("--group");
60	const OPEN_GATES = new Set(argValues("--gate"));
61	
62	function loadGroups() {
63	  if (!existsSync(CORRECTIONS_DIR)) return [];
64	  return readdirSync(CORRECTIONS_DIR)
65	    .filter((f) => f.endsWith(".json"))
66	    .sort()
67	    .map((file) => {
68	      const path = join(CORRECTIONS_DIR, file);
69	      let raw;
70	      try {
71	        raw = JSON.parse(readFileSync(path, "utf8"));
72	      } catch (error) {
73	        throw new Error(`${file}: not valid JSON — ${error.message}`);
74	      }
75	      for (const field of ["group", "why", "edits"]) {
76	        if (raw[field] === undefined) throw new Error(`${file}: missing "${field}"`);
77	      }
78	      return { file, ...raw };
79	    });
80	}
81	
82	/** A short window of text around an index, flattened onto one line. */
83	function context(text, index, length, pad = 130) {
84	  const before = text.slice(Math.max(0, index - pad), index).replace(/\s+/g, " ");
85	  const hit = text.slice(index, index + length).replace(/\s+/g, " ");
86	  const after = text.slice(index + length, index + length + pad).replace(/\s+/g, " ");
87	  return { before, hit, after };
88	}
89	
90	function printContext({ before, hit, after }, indent = "      ") {
91	  console.log(`${indent}…${before}[[${hit}]]${after}…`);
92	}
93	
94	/** Every match of every detect pattern, across one body. */
95	function sweepBody(body, patterns) {
96	  const hits = [];
97	  for (const source of patterns) {
98	    const re = new RegExp(source, "gi");
99	    let m;
100	    while ((m = re.exec(body)) !== null) {
101	      hits.push({ pattern: source, index: m.index, length: m[0].length });
102	      if (m[0].length === 0) re.lastIndex++; // never loop forever on an empty match
103	    }
104	  }
105	  return hits.sort((a, b) => a.index - b.index);
106	}
107	
108	async function main() {
109	  loadEnv();
110	  if (!process.env.DATABASE_URL) {
111	    console.error("DATABASE_URL is not set, and .env did not provide one.");
112	    process.exit(1);
113	  }
114	
115	  const groups = loadGroups().filter((g) => ONLY_GROUPS.length === 0 || ONLY_GROUPS.includes(g.group));
116	  if (groups.length === 0) {
117	    console.error(`No correction groups found in ${CORRECTIONS_DIR}.`);
118	    process.exit(1);
119	  }
120	
121	  const db = new PrismaClient();
122	  let stale = 0;
123	  let residue = 0;
124	  const stubs = [];
125	
126	  try {
127	    const rows = await db.blogPost.findMany({ select: { slug: true, bodyHtml: true } });
128	    const bySlug = new Map(rows.map((r) => [r.slug, r]));
129	    // Planned bodies, so the sweep at the end judges the CORRECTED text rather
130	    // than what is in the database right now.
131	    const planned = new Map(rows.map((r) => [r.slug, r.bodyHtml]));
132	    const writes = new Map();
133	
134	    console.log(
135	      `${APPLY ? "APPLYING" : "DRY RUN — nothing will be written"} against ${rows.length} BlogPost rows.\n`,
136	    );
137	
138	    for (const group of groups) {
139	      const gated = group.gate && !OPEN_GATES.has(group.gate);
140	      console.log(`── ${group.group}  (${group.file})`);
141	      console.log(`   ${group.why}`);
142	      if (gated) {
143	        console.log(`   SKIPPED — gated behind --gate ${group.gate}.`);
144	        if (group.gateWhy) console.log(`   ${group.gateWhy}`);
145	        console.log("");
146	        continue;
147	      }
148	      if (group.gate) console.log(`   gate ${group.gate}: OPEN (asserted on the command line)`);
149	
150	      let applied = 0;
151	      let already = 0;
152	      for (const edit of group.edits) {
153	        const row = bySlug.get(edit.slug);
154	        if (!row) {
155	          console.log(`   MISSING ROW  ${edit.slug} — no such slug in this database.`);
156	          stale++;
157	          continue;
158	        }
159	        const body = planned.get(edit.slug);
160	
161	        if (body.includes(edit.find)) {
162	          const index = body.indexOf(edit.find);
163	          console.log(`   change  ${edit.slug}`);
164	          console.log(`      -  ${edit.find.replace(/\s+/g, " ")}`);
165	          console.log(`      +  ${edit.replace.replace(/\s+/g, " ")}`);
166	          if (edit.note) console.log(`      why: ${edit.note}`);
167	          const next = body.slice(0, index) + edit.replace + body.slice(index + edit.find.length);
168	          if (next.includes(edit.find)) {
169	            console.log(`      NOTE: "${edit.slug}" contains this text more than once — rerun to catch the rest.`);
170	          }
171	          planned.set(edit.slug, next);
172	          writes.set(edit.slug, next);
173	          applied++;
174	        } else if (edit.replace && body.includes(edit.replace)) {
175	          already++;
176	        } else {
177	          console.log(`   STALE   ${edit.slug} — neither the old text nor the new text is present.`);
178	          console.log(`      looked for: ${edit.find.replace(/\s+/g, " ").slice(0, 120)}…`);
179	          console.log("      The live copy has drifted. Re-read the row and rewrite this edit.");
180	          stale++;
181	        }
182	      }
183	      console.log(`   ${applied} to change, ${already} already corrected.`);
184	
185	      // ── Sweep every row, not just the ones this group names ───────────────
186	      if (Array.isArray(group.detect) && group.detect.length > 0) {
187	        // `ignore` exists because these patterns cannot tell an affirmative
188	        // claim from a denial of one: an article whose whole point is "a
189	        // working contact form is exactly what you cannot have" matches the
190	        // same words as one promising it. Rather than write ever-cleverer
191	        // negative lookbehinds, a hit whose surrounding context matches an
192	        // ignore pattern is dropped — and the ignore list is short, explicit
193	        // and reviewable in the group file.
194	        const ignores = (group.ignore ?? []).map((source) => new RegExp(source, "i"));
195	        const found = [];
196	        for (const [slug, body] of planned) {
197	          for (const hit of sweepBody(body, group.detect)) {
198	            const ctx = context(body, hit.index, hit.length, 200);
199	            const window = `${ctx.before}${ctx.hit}${ctx.after}`;
200	            if (ignores.some((re) => re.test(window))) continue;
201	            found.push({ slug, ...hit, ...context(body, hit.index, hit.length) });
202	          }
203	        }
204	        if (found.length > 0) {
205	          residue += found.length;
206	          console.log(`\n   RESIDUE — ${found.length} place(s) still matching this group's detect patterns:`);
207	          for (const f of found) {
208	            console.log(`    ${f.slug}`);
209	            printContext(f);
210	            stubs.push({ group: group.group, slug: f.slug, find: f.hit, replace: "", note: "TODO" });
211	          }
212	          console.log("   Each needs a hand-written replacement — this script will not guess one.");
213	        } else {
214	          console.log("   sweep clean — no row matches this group's detect patterns.");
215	        }
216	      }
217	      console.log("");
218	    }
219	
220	    if (APPLY && writes.size > 0) {
221	      for (const [slug, bodyHtml] of writes) {
222	        await db.blogPost.update({ where: { slug }, data: { bodyHtml } });
223	      }
224	      console.log(`Wrote ${writes.size} row(s).`);
225	    } else if (writes.size > 0) {
226	      console.log(`${writes.size} row(s) would change. Re-run with --apply.`);
227	    } else {
228	      console.log("Nothing to change.");
229	    }
230	
231	    if (EMIT_STUBS && stubs.length > 0) {
232	      const out = join(CORRECTIONS_DIR, "pending.generated.json");
233	      writeFileSync(out, `${JSON.stringify({ note: "Generated by --emit-stubs. Fill in each `replace`, move the entries into the right group file, then delete this file.", edits: stubs }, null, 2)}\n`);
234	      console.log(`Wrote ${stubs.length} stub(s) to ${out}.`);
235	    }
236	
237	    if (stale > 0) console.log(`\n${stale} stale or missing edit(s).`);
238	    if (residue > 0) console.log(`${residue} uncorrected occurrence(s) still in the database.`);
239	  } finally {
240	    await db.$disconnect();
241	  }
242	
243	  process.exit(stale + residue > 0 ? 1 : 0);
244	}
245	
246	main().catch((error) => {
247	  console.error(error);
248	  process.exit(1);
249	});
