import { loadEnv } from "../../../../../kodely-prod/scripts/seo/lib.mjs";
import { validateAll } from "../../../../../kodely-prod/scripts/seo/validate.mjs";

loadEnv("C:/Users/edmem/kodely-prod/.env");
const { PrismaClient } = await import("@prisma/client");

// Same splitter I intend to ship.
const TAG_RE = /<\/?([a-zA-Z][a-zA-Z0-9]*)((?:[^>"']|"[^"]*"|'[^']*')*?)\s*\/?>/g;

function splitTopLevelBlocks(html) {
  const blocks = [];
  let depth = 0;
  let start = 0;
  let match;
  TAG_RE.lastIndex = 0;
  while ((match = TAG_RE.exec(html)) !== null) {
    const full = match[0];
    const isClose = full.startsWith("</");
    const selfClosing = /\/>$/.test(full);
    if (selfClosing) continue;
    if (isClose) {
      depth--;
      if (depth <= 0) {
        blocks.push(html.slice(start, match.index + full.length).trim());
        start = match.index + full.length;
        depth = 0;
      }
    } else {
      if (depth === 0) {
        const between = html.slice(start, match.index).trim();
        if (between) blocks.push(between);
        start = match.index;
      }
      depth++;
    }
  }
  const tail = html.slice(start).trim();
  if (tail) blocks.push(tail);
  return blocks;
}

const db = new PrismaClient();
const rows = await db.blogPost.findMany({ orderBy: { slug: "asc" } });
const articles = rows.map((r) => ({
  file: r.slug,
  expectedSlug: r.slug,
  slug: r.slug,
  title: r.title,
  metaDescription: r.metaDescription,
  category: r.category,
  targetKeyword: r.targetKeyword,
  body: splitTopLevelBlocks(r.bodyHtml),
