    for (const p of problems) console.log("   -", p);
  }
  if (warnings.length) {
    console.log(`warn ${article.slug}: ${warnings.join(" | ")}`);
  }
}
console.log(`${articles.length} rows — ${fail} failing.`);
await db.$disconnect();

