// The render contract for a BlogPost body, enforced on the server.
//
// ── WHY THIS FILE IS AN ADAPTER AND NOT A RULE SET ────────────────────────
//
// scripts/seo/validate.mjs already encodes the contract that
// app/blog/[slug]/page.tsx imposes: the allowed tag set (.article-body styles
// only h2/h3/p/ul/ol/li/a/strong/code/table/th/td/blockquote), balanced tags,
// no <h1> because the page renders post.title as the only one, no external
// src/href, no inline style or event handler, no bare "<" / ">" / "&", title
// and metaDescription lengths, the category vocabulary, and the thin-content
// warnings. Twenty-odd checks, each one written against a line of the render
// code.
//
// A second copy of those rules living in the admin panel is the failure mode
// worth designing against: the two drift, and the one that drifts is the one
// deciding whether unsanitised markup reaches a public page. So this module
// IMPORTS validate.mjs and calls its exported `validateAll`. It contributes no
// checks of its own.
//
// It DOES contribute one transform, because the two callers hold the article in
// different shapes. validate.mjs is built for content/seo/*.json, where the body
// is an ARRAY of block-level HTML strings and `bodyHtml` is
// `body.join("\n")` (see scripts/seo/lib.mjs). The database stores only the
// joined string. `splitTopLevelBlocks` inverts that join so a database row can
// be handed to the validator unchanged — it re-derives the ARRAY, never the
// RULES. Verified against all 17 local rows: `splitTopLevelBlocks(bodyHtml)
// .join("\n") === bodyHtml.trim()` for every one.
//
// Importing an .mjs from scripts/ into a server module works because this file
// only ever runs on the server (it is imported by Server Components and by
// "use server" actions), validate.mjs's own `main()` is guarded behind an
// `import.meta.url === argv[1]` check that a bundled import never satisfies,
// and nothing here calls `loadArticles()` — the one export that touches the
// filesystem — since every article is passed in explicitly.

import { validateAll } from "@/scripts/seo/validate.mjs";

/** The six columns of BlogPost the validator judges. */
export type PostFields = {
  slug: string;
  title: string;
  metaDescription: string;
  category: string;
  targetKeyword: string;
  bodyHtml: string;
};

export type ValidationResult = {
  /** Refuses the save. */
  problems: string[];
  /** Advisory only — thin body, no <h2>, no CTA link. */
  warnings: string[];
};

export const EMPTY_RESULT: ValidationResult = { problems: [], warnings: [] };

// Same expression validate.mjs uses to walk the tag stream. Duplicated here for
// ONE purpose — finding where a top-level element ends so the body can be split
// back into blocks — and never to decide whether anything is allowed. If it and
// the validator's copy ever disagree, the consequence is a differently-grouped
// `body` array, not a differently-enforced rule.
const TAG_RE = /<\/?([a-zA-Z][a-zA-Z0-9]*)((?:[^>"']|"[^"]*"|'[^']*')*?)\s*\/?>/g;

/**
 * The inverse of `body.join("\n")` in scripts/seo/lib.mjs: one entry per
 * top-level element, in document order.
 *
 * Depth-counted rather than split on newlines, so a body an admin has
 * pretty-printed across several lines (a table, most likely) still yields one
 * block per element instead of a dozen fragments that would each be reported as
 * "does not start with a block element".
 *
 * Text sitting at depth zero is emitted as its own block precisely BECAUSE the
 * validator will then reject it — a bare run of prose outside any element is
 * exactly what the article contract forbids.
 */
export function splitTopLevelBlocks(html: string): string[] {
  const blocks: string[] = [];
  let depth = 0;
  let start = 0;
  let match: RegExpExecArray | null;

  TAG_RE.lastIndex = 0;
  while ((match = TAG_RE.exec(html)) !== null) {
    const full = match[0];
    // A self-closing tag opens nothing. The validator rejects it separately;
    // here it must simply not unbalance the depth count.
    if (/\/>$/.test(full)) continue;

    if (full.startsWith("</")) {
      depth--;
      if (depth <= 0) {
        blocks.push(html.slice(start, match.index + full.length).trim());
        start = match.index + full.length;
        depth = 0;
      }
    } else {
      if (depth === 0) {
        const between = html.slice(start, match.index).trim();
        if (between) blocks.push(between);
        start = match.index;
      }
      depth++;
    }
  }

  const tail = html.slice(start).trim();
  if (tail) blocks.push(tail);
  return blocks;
}

/**
 * A database row in the shape `validate.mjs` expects of a file on disk.
 *
 * `file` and `expectedSlug` exist only to satisfy the filename checks, which
 * have no meaning for a row: setting `expectedSlug` to the slug itself makes
 * the "slug does not match its filename" check a tautology rather than a
 * spurious failure. Nothing else is faked.
 */
function toArticle(post: PostFields) {
  return {
    file: `${post.slug} (database row)`,
    expectedSlug: post.slug,
    slug: post.slug,
    title: post.title,
    metaDescription: post.metaDescription,
    category: post.category,
    targetKeyword: post.targetKeyword,
    body: splitTopLevelBlocks(post.bodyHtml),
    bodyHtml: post.bodyHtml,
  };
}

/** validate.mjs is plain JS, so its arrays arrive untyped. Pin them here. */
function toResult(entry: { problems: unknown[]; warnings: unknown[] }): ValidationResult {
  return {
    problems: entry.problems.map(String),
    warnings: entry.warnings.map(String),
  };
}

/**
 * Every post judged together, keyed by slug.
 *
 * Passed as one batch on purpose: three of the validator's checks — duplicate
 * slug, duplicate title, duplicate metaDescription — and its internal-link
 * check ("does /blog/x point at an article that exists?") are only meaningful
 * across the whole corpus. Validating rows one at a time would silently drop
 * four checks.
 *
 * Duplicate-detection reports the SECOND occurrence, so the order of `posts`
 * decides which of a colliding pair is flagged. That matches the CLI, which
 * orders by filename.
 */
export function validatePosts(posts: PostFields[]): Map<string, ValidationResult> {
  const out = new Map<string, ValidationResult>();
  for (const entry of validateAll(posts.map(toArticle))) {
    out.set(String(entry.article.slug), toResult(entry));
  }
  return out;
}

/**
 * One draft, judged against every other published post.
 *
 * The draft goes LAST so the corpus claims its own titles and descriptions
 * first — meaning a collision is reported against the row being edited, which
 * is the one the admin can actually do something about, rather than against
 * some unrelated post they cannot see from here.
 *
 * `others` must not contain the draft's own slug, or it collides with itself.
 */
export function validateDraft(draft: PostFields, others: PostFields[]): ValidationResult {
  const corpus = others.filter((p) => p.slug !== draft.slug);
  const results = validatePosts([...corpus, draft]);
  return results.get(draft.slug) ?? EMPTY_RESULT;
}

// Which published posts still say something that is no longer true.
//
// ── WHERE THE PATTERNS COME FROM ──────────────────────────────────────────
//
// content/seo/corrections/*.json already holds them, as data, because
// scripts/seo/correct-live.mjs needs them: each group carries `detect` (regex
// sources describing the CLAIM being corrected), `ignore` (context windows that
// look like the claim but are a denial of it), a `why` written against the code
// that makes the claim false, and — for export-claim — a `gate` naming the
// deploy that flips it.
//
// This module reads those same files. It writes no patterns of its own except
// the one supplement documented below, and it applies `ignore` with the same
// ±200-character window `correct-live.mjs` uses, so the panel and the corrector
// agree on what counts as a hit.
//
// ── WHAT IT DELIBERATELY DOES NOT DO ──────────────────────────────────────
//
// It never rewrites anything. correct-live.mjs applies LITERAL, hand-written
// replacements one slug at a time and refuses to guess; this surface is the
// half that was missing — letting a human READ the flagged sentence in context
// and decide. A regex that is good enough to find 56 suspect sentences is
// nowhere near good enough to rewrite them, and the first hit found in the
// local database proves it: "no export negotiation" matches the export-claim
// detector and means the opposite of what the detector is looking for.

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** A correction group as it sits on disk. Only the fields this page reads. */
type CorrectionGroupFile = {
  group?: unknown;
  why?: unknown;
  gate?: unknown;
  gateWhy?: unknown;
  detect?: unknown;
  ignore?: unknown;
};

export type StaleGroup = {
  /** Group name, e.g. "credit-figure". */
  group: string;
  /** Why the claim is wrong, verbatim from the correction file. */
  why: string;
  /** Set when the correction is only true after a named deploy. */
  gate: string | null;
  gateWhy: string | null;
  /** Where the group is defined, for an operator who wants to read it. */
  source: string;
  match: (bodyHtml: string) => StaleHit[];
};

export type StaleHit = {
  group: string;
  /** The matched text, whitespace flattened. */
  hit: string;
  /** Surrounding prose, whitespace flattened, so the hit can be judged in context. */
  before: string;
  after: string;
};

/** Newest-first slice of text around a match, flattened onto one line. */
function context(text: string, index: number, length: number, pad: number) {
  return {
    before: text.slice(Math.max(0, index - pad), index).replace(/\s+/g, " "),
    hit: text.slice(index, index + length).replace(/\s+/g, " "),
    after: text.slice(index + length, index + length + pad).replace(/\s+/g, " "),
  };
}

function asStrings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((v): v is string => typeof v === "string") : [];
}

/**
 * A matcher for one correction group's `detect`/`ignore` pair.
 *
 * `ignore` is checked against a ±200-character window, exactly as
 * correct-live.mjs does it — the group files were tuned against that width, and
 * a narrower window would resurrect hits their authors already ruled out.
 */
function regexMatcher(group: string, detect: string[], ignore: string[]) {
  const ignores = ignore.map((source) => new RegExp(source, "i"));
  return (bodyHtml: string): StaleHit[] => {
    const hits: StaleHit[] = [];
    for (const source of detect) {
      const re = new RegExp(source, "gi");
      let m: RegExpExecArray | null;
      while ((m = re.exec(bodyHtml)) !== null) {
        // Never loop forever on a zero-width match — same guard as the CLI.
        if (m[0].length === 0) re.lastIndex++;
        const wide = context(bodyHtml, m.index, m[0].length, 200);
        if (ignores.some((ig) => ig.test(`${wide.before}${wide.hit}${wide.after}`))) continue;
        hits.push({ group, ...context(bodyHtml, m.index, m[0].length, 130) });
      }
    }
    return hits.sort((a, b) => a.before.length - b.before.length);
  };
}

/**
 * The one pattern this panel adds on top of the correction files.
 *
 * The brief names three stale claims to flag. Two are already correction
 * groups (`credit-figure`, `export-claim`). The third — a capability TABLE
 * whose export row reads "Not yet" — is not, because correct-live.mjs works in
 * literal replacements and a table cell has no sentence to replace; it needs a
 * human to rewrite the row. It is a two-part condition rather than one regex
 * (a <tr> that is ABOUT export AND says "Not yet"), which is also why it does
 * not fit the `detect` array shape.
 *
 * If it later earns a literal correction, it belongs in
 * content/seo/corrections/ with the others and should be deleted from here.
 */
const EXPORT_ROW_GROUP: StaleGroup = {
  group: "export-row",
  why:
    'A capability table whose export/download/zip row reads "Not yet". True today, false the moment ' +
    "app/api/projects/[id]/export/route.ts deploys — the same inversion export-claim covers for prose, " +
    "which literal find-and-replace cannot reach inside a table cell.",
  gate: "export-shipped",
  gateWhy:
    "Same window as export-claim: correct before the deploy and a true row becomes false; correct long " +
    "after and the table denies a shipped feature.",
  source: "app/admin/content/stale.ts",
  match: (bodyHtml) => {
    const hits: StaleHit[] = [];
    for (const m of bodyHtml.matchAll(/<tr>[\s\S]{0,600}?<\/tr>/gi)) {
      const row = m[0];
      if (!/\bnot yet\b/i.test(row)) continue;
      if (!/\b(zip|export|download|source code)\b/i.test(row)) continue;
      hits.push({
        group: "export-row",
        before: "",
        hit: row.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
        after: "",
      });
    }
    return hits;
  },
};

/**
 * Every group, loaded fresh on each request.
 *
 * Read from disk rather than imported so that adding a correction file — the
 * normal way a new class of wrong claim gets named — makes it appear here
 * without touching this code. A missing or unreadable directory yields the
 * supplement alone rather than throwing: a panel that 500s because a content
 * file is malformed is a panel nobody can use to fix content.
 */
export function loadStaleGroups(): StaleGroup[] {
  const dir = join(process.cwd(), "content", "seo", "corrections");
  const groups: StaleGroup[] = [];

  let files: string[] = [];
  try {
    files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
  } catch {
    files = [];
  }

  for (const file of files) {
    let raw: CorrectionGroupFile;
    try {
      raw = JSON.parse(readFileSync(join(dir, file), "utf8")) as CorrectionGroupFile;
    } catch {
      continue;
    }
    const detect = asStrings(raw.detect);
    if (detect.length === 0) continue;
    const name = typeof raw.group === "string" ? raw.group : file.replace(/\.json$/, "");
    groups.push({
      group: name,
      why: typeof raw.why === "string" ? raw.why : "",
      gate: typeof raw.gate === "string" ? raw.gate : null,
      gateWhy: typeof raw.gateWhy === "string" ? raw.gateWhy : null,
      source: `content/seo/corrections/${file}`,
      match: regexMatcher(name, detect, asStrings(raw.ignore)),
    });
  }

  groups.push(EXPORT_ROW_GROUP);
  return groups;
}

/** Every group's hits against one body, in group order. */
export function sweepBody(bodyHtml: string, groups: StaleGroup[]): StaleHit[] {
  return groups.flatMap((g) => g.match(bodyHtml));
}

