import type { ReactNode } from "react";

// Presentational helpers for /admin/content.
//
// Local copies of the vocabulary established in app/admin/page.tsx and
// app/admin/users/ui.tsx — rounded-xl hairline borders, text-sm, tabular-nums
// on every figure, monochrome except where a colour carries status meaning — so
// this section reads as part of the same panel. Duplicated rather than imported
// for the same reason app/admin/flags/page.tsx duplicates them: those helpers
// belong to the /admin/users route folder.
//
// Not a route: only page/layout/route filenames are routable, so this file is
// safe inside app/admin/content/.

export function formatDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function formatDateTime(d: Date): string {
  return d.toISOString().replace("T", " ").slice(0, 19);
}

export function truncate(text: string, max = 60): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

/** Same arithmetic as readingTime() in app/blog/[slug]/page.tsx. */
export function wordCount(html: string): number {
  return html.replace(/<[^>]+>/g, " ").trim().split(/\s+/).filter(Boolean).length;
}

export const buttonClass =
  "rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current dark:border-white/10 dark:hover:bg-white/5";

export const primaryButtonClass =
  "rounded-xl border border-black/70 bg-black px-3 py-2 text-sm font-medium text-white hover:bg-black/85 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current disabled:opacity-40 dark:border-white/70 dark:bg-white dark:text-black dark:hover:bg-white/85";

export const fieldClass =
  "w-full rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30";

export const linkClass =
  "underline-offset-4 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current";

export function StatTile({
  label,
  value,
  hint,
  tone,
}: {
  label: string;
  value: ReactNode;
  hint?: ReactNode;
  tone?: "warn" | "bad";
}) {
  return (
    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
      <div
        className={`mt-1 text-xl font-semibold tabular-nums ${
          tone === "warn"
            ? "text-amber-600 dark:text-amber-500"
            : tone === "bad"
              ? "text-red-600 dark:text-red-400"
              : ""
        }`}
      >
        {value}
      </div>
      {hint ? <div className="mt-1 text-xs text-black/50 dark:text-white/50">{hint}</div> : null}
    </div>
  );
}

export function TableFrame({ children }: { children: ReactNode }) {
  return (
    <div className="overflow-x-auto rounded-xl border border-black/10 dark:border-white/10">
      <table className="w-full text-left text-sm">{children}</table>
    </div>
  );
}

export function Th({ children, align = "left" }: { children: ReactNode; align?: "left" | "right" }) {
  return (
    <th className={`px-4 py-2 font-medium ${align === "right" ? "text-right" : ""}`}>{children}</th>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
      {children}
    </div>
  );
}

/**
 * A validator verdict. Problems are red because they refuse the save; warnings
 * are amber because they never do. Colour is the only thing separating them, so
 * each list is also labelled in words.
 */
export function VerdictList({
  problems,
  warnings,
  okLabel = "Passes every check in scripts/seo/validate.mjs.",
}: {
  problems: string[];
  warnings: string[];
  okLabel?: string;
}) {
  if (problems.length === 0 && warnings.length === 0) {
    return (
      <p className="text-sm text-emerald-700 dark:text-emerald-400">{okLabel}</p>
    );
  }
  return (
    <div className="space-y-3 text-sm">
      {problems.length > 0 ? (
        <div>
          <div className="text-xs font-medium uppercase tracking-wide text-red-600 dark:text-red-400">
            {problems.length} {problems.length === 1 ? "problem" : "problems"} — save refused
          </div>
          <ul className="mt-1.5 list-disc space-y-1 pl-5 text-red-700 dark:text-red-300">
            {problems.map((p) => (
              <li key={p}>{p}</li>
            ))}
          </ul>
        </div>
      ) : null}
      {warnings.length > 0 ? (
        <div>
          <div className="text-xs font-medium uppercase tracking-wide text-amber-600 dark:text-amber-500">
            {warnings.length} {warnings.length === 1 ? "warning" : "warnings"} — does not block
          </div>
          <ul className="mt-1.5 list-disc space-y-1 pl-5 text-amber-700 dark:text-amber-500">
            {warnings.map((w) => (
              <li key={w}>{w}</li>
            ))}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { validateDraft, type PostFields, type ValidationResult } from "./validation";

// Server Actions for /admin/content.
//
// ── THE SECURITY ARGUMENT, STATED ONCE ────────────────────────────────────
//
// `bodyHtml` is injected into a public page with dangerouslySetInnerHTML and no
// sanitisation (app/blog/[slug]/page.tsx line 118). Two things follow, and both
// are enforced here rather than in the browser:
//
// 1. A Server Action is a POST endpoint against the route, reachable by anyone
//    who can send the request. Rendering the editor only on an admin page is
//    not an authorization boundary — see the Next.js Server Actions guide and
//    the argument in getAdminUser's doc comment. So this re-checks ADMIN
//    itself, on every call, and throws rather than no-oping. There is no other
//    write path to bodyHtml in the application.
//
// 2. Client-side validation is a convenience for the person typing; it is not a
//    control. Every field is re-validated on the server, from the submitted
//    FormData, immediately before the write — and a draft with any problem is
//    refused. The editor cannot be talked into storing markup the blog page
//    cannot safely render, because the check does not live in the editor.
//
// The write is deliberately narrow: five columns of one row, addressed by a
// slug that must already exist. No create path, no delete path, no bulk path.
// Correcting 56 live pages with a find-and-replace is exactly how one wrong
// sentence becomes 56 wrong ones, so this surface only ever changes the one
// post an admin is looking at.
//
// NOT AUDIT LOGGED, and that is a gap rather than a decision: lib/admin-audit.ts
// keeps a deliberately CLOSED vocabulary (ADMIN_ACTIONS) and has no name for a
// content write, and this change is not permitted to edit lib/. A
// `blog_post.updated` action belongs in that vocabulary — it is a write to
// public content, which is the strongest case the module makes for recording
// something — and should be added with a call from `savePost` below.

export type EditorDraft = {
  title: string;
  metaDescription: string;
  category: string;
  targetKeyword: string;
  bodyHtml: string;
};

export type EditorState = {
  /**
   * idle    — nothing submitted yet
   * preview — validated, not written; `previewHtml` is set when it passed
   * saved   — written
   * refused — validation failed, nothing written
   * error   — the row is gone, or the write itself failed
   */
  status: "idle" | "preview" | "saved" | "refused" | "error";
  message: string;
  problems: string[];
  warnings: string[];
  /**
   * Set only when validation passed. The editor renders it; a body with any
   * problem is never handed back for rendering, so the preview pane cannot
   * become the place where malformed markup gets exercised.
   */
  previewHtml: string | null;
  /** Whether the submitted draft differs from the stored row. */
  dirty: boolean;
};

export const INITIAL_EDITOR_STATE: EditorState = {
  status: "idle",
  message: "",
  problems: [],
  warnings: [],
  previewHtml: null,
  dirty: false,
};

async function requireAdmin() {
  const admin = await getAdminUser();
  if (!admin) throw new Error("FORBIDDEN");
  return admin;
}

function field(formData: FormData, name: string): string {
  const value = formData.get(name);
  return typeof value === "string" ? value : "";
}

/**
 * Normalises what a <textarea> and an <input> actually submit.
 *
 * A browser sends textarea content with CRLF line endings, and the stored
 * bodies use LF (scripts/seo/lib.mjs joins blocks with "\n"). Left alone, every
 * save would rewrite every line of a body the admin did not touch, which turns
 * "fixed one sentence" into an unreviewable diff. Single-line fields are
 * trimmed; the body is only stripped of trailing whitespace, since leading
 * structure is meaningful.
 */
function readDraft(formData: FormData): EditorDraft {
  return {
    title: field(formData, "title").trim(),
    metaDescription: field(formData, "metaDescription").trim(),
    category: field(formData, "category").trim(),
    targetKeyword: field(formData, "targetKeyword").trim(),
    bodyHtml: field(formData, "bodyHtml").replace(/\r\n/g, "\n").trim(),
  };
}

function isSame(a: EditorDraft, b: EditorDraft): boolean {
  return (
    a.title === b.title &&
    a.metaDescription === b.metaDescription &&
    a.category === b.category &&
    a.targetKeyword === b.targetKeyword &&
    a.bodyHtml === b.bodyHtml
  );
}

/**
 * Every other post, for the four validator checks that only mean anything
 * across the corpus: duplicate slug, duplicate title, duplicate
 * metaDescription, and whether a /blog/… link points at a post that exists.
 */
async function corpus(excludeSlug: string): Promise<PostFields[]> {
  return db.blogPost.findMany({
    where: { slug: { not: excludeSlug } },
    orderBy: { slug: "asc" },
    select: {
      slug: true,
      title: true,
      metaDescription: true,
      category: true,
      targetKeyword: true,
      bodyHtml: true,
    },
  });
}

/**
 * Validate a draft the same way the save path does, without writing.
 *
 * Exported so the edit page can show the STORED row's verdict on load: a post
 * that already fails is worth knowing about before you start typing, and it is
 * the honest explanation for a save the panel is about to refuse.
 */
export async function checkDraft(slug: string, draft: EditorDraft): Promise<ValidationResult> {
  await requireAdmin();
  return validateDraft({ slug, ...draft }, await corpus(slug));
}

/**
 * The editor's only action. `intent` decides whether a clean draft is written
 * or merely rendered; an unclean one is neither, whichever button was pressed.
 */
export async function savePostAction(
  _prev: EditorState,
  formData: FormData,
): Promise<EditorState> {
  await requireAdmin();

  const slug = field(formData, "slug");
  const intent = field(formData, "intent") === "save" ? "save" : "preview";
  const draft = readDraft(formData);

  const existing = await db.blogPost.findUnique({
    where: { slug },
    select: {
      slug: true,
      title: true,
      metaDescription: true,
      category: true,
      targetKeyword: true,
      bodyHtml: true,
    },
  });
  if (!existing) {
    return {
      ...INITIAL_EDITOR_STATE,
      status: "error",
      message: `No post with slug “${slug}”. Nothing was written.`,
    };
  }

  const dirty = !isSame(draft, existing);
  const { problems, warnings } = validateDraft({ slug, ...draft }, await corpus(slug));

  if (problems.length > 0) {
    return {
      status: "refused",
      message:
        intent === "save"
          ? "Not saved. The body is rendered into a public page unsanitised, so an invalid draft is never written."
          : "Cannot preview: this draft would not render correctly.",
      problems,
      warnings,
      previewHtml: null,
      dirty,
    };
  }

  if (intent === "preview") {
    return {
      status: "preview",
      message: dirty
        ? "Valid. This is how the post would render — nothing has been written yet."
        : "Valid, and identical to what is published right now.",
      problems,
      warnings,
      previewHtml: draft.bodyHtml,
      dirty,
    };
  }

  if (!dirty) {
    return {
      status: "preview",
      message: "Nothing changed, so nothing was written — updatedAt is left alone.",
      problems,
      warnings,
      previewHtml: draft.bodyHtml,
      dirty: false,
    };
  }

  await db.blogPost.update({
    where: { slug },
    data: {
      title: draft.title,
      metaDescription: draft.metaDescription,
      category: draft.category,
      targetKeyword: draft.targetKeyword,
      bodyHtml: draft.bodyHtml,
    },
  });

  // app/blog/[slug]/page.tsx is force-static with revalidate 3600, so without
  // this the correction sits invisible for up to an hour — on a panel whose
  // entire purpose is fixing something wrong that is live right now. The index
  // is force-dynamic but is invalidated too, since a title or category change
  // moves the card there as well.
  revalidatePath(`/blog/${slug}`);
  revalidatePath("/blog");

  return {
    status: "saved",
    message: "Saved and published. /blog and this post were revalidated.",
    problems,
    warnings,
    previewHtml: draft.bodyHtml,
    dirty: false,
  };
}

// The shape passed between the editor form and its Server Action.
//
// Separate from actions.ts because a "use server" module may only export async
// functions — a plain constant like INITIAL_EDITOR_STATE exported from there is
// a build error. Keeping the vocabulary in its own module also means the client
// component can import the state type without pulling the action's server
// imports (Prisma, the validator) into its dependency graph.

export type EditorDraft = {
  title: string;
  metaDescription: string;
  category: string;
  targetKeyword: string;
  bodyHtml: string;
};

export type EditorState = {
  /**
   * idle    — nothing submitted yet
   * preview — validated, not written; `previewHtml` is set
   * saved   — written
   * refused — validation failed, nothing written
   * error   — the row is gone, or the write itself failed
   */
  status: "idle" | "preview" | "saved" | "refused" | "error";
  message: string;
  problems: string[];
  warnings: string[];
  /**
   * Set only when validation passed. The editor renders it; a body with any
   * problem is never handed back for rendering, so the preview pane cannot
   * become the place where malformed markup gets exercised.
   */
  previewHtml: string | null;
  /** Whether the submitted draft differs from the stored row. */
  dirty: boolean;
};

export const INITIAL_EDITOR_STATE: EditorState = {
  status: "idle",
  message: "",
  problems: [],
  warnings: [],
  previewHtml: null,
  dirty: false,
};

