// Scratch: confirm no BlogPost row was modified during this session, by
// comparing every row against the article on disk it was seeded from and by
// checking updatedAt is not recent.
import { readFileSync, existsSync } from "node:fs";
import { loadEnv } from "file:///C:/Users/edmem/kodely-prod/scripts/seo/lib.mjs";

loadEnv("C:/Users/edmem/kodely-prod/.env");
const { PrismaClient } = await import(
  "file:///C:/Users/edmem/kodely-prod/node_modules/@prisma/client/default.js"
);

const db = new PrismaClient();
const rows = await db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });

console.log("rows:", rows.length);
console.log("newest updatedAt:", rows[0].updatedAt.toISOString(), rows[0].slug);
console.log("oldest updatedAt:", rows[rows.length - 1].updatedAt.toISOString());
console.log("now:", new Date().toISOString());
const recent = rows.filter((r) => Date.now() - r.updatedAt.getTime() < 6 * 3600 * 1000);
console.log("rows updated in the last 6 hours:", recent.length);

let drift = 0;
for (const r of rows) {
  const path = `C:/Users/edmem/kodely-prod/content/seo/${r.slug}.json`;
  if (!existsSync(path)) {
    console.log("no source file for", r.slug);
    continue;
  }
  const j = JSON.parse(readFileSync(path, "utf8"));
  const same =
    j.title === r.title &&
    j.metaDescription === r.metaDescription &&
    j.category === r.category &&
    j.targetKeyword === r.targetKeyword &&
    j.body.join("\n") === r.bodyHtml;
  if (!same) {
    drift++;
    console.log("DIFFERS FROM content/seo:", r.slug);
  }
}
console.log(`rows differing from their content/seo source: ${drift}`);
await db.$disconnect();

